package com.lyrashop.user.repository; import java.util.*;import org.springframework.data.jpa.repository.*;import org.springframework.data.repository.query.Param;import jakarta.persistence.LockModeType;import com.lyrashop.user.entity.LoyaltyAccount; public interface LoyaltyAccountRepository extends JpaRepository<LoyaltyAccount,UUID>{@Lock(LockModeType.PESSIMISTIC_WRITE)@Query("select a from LoyaltyAccount a where a.userId=:userId")Optional<LoyaltyAccount> findForUpdate(@Param("userId")UUID userId);}
